// ---------- generic helpers ----------

const randInt = (lo, hi) => Math.floor(Math.random() * (hi - lo + 1)) + lo;
const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
const fmt = (n) => n.toLocaleString("en-US");

function countCarries(a, b) {
  const A = String(a).split("").map(Number).reverse();
  const B = String(b).split("").map(Number).reverse();
  let carry = 0, c = 0;
  for (let i = 0; i < Math.max(A.length, B.length); i++) {
    carry = (A[i] || 0) + (B[i] || 0) + carry >= 10 ? 1 : 0;
    if (carry) c++;
  }
  return c;
}

function countBorrows(a, b) {
  const A = String(a).split("").map(Number);
  const B = String(b).padStart(A.length, "0").split("").map(Number);
  const adj = [...A];
  let c = 0;
  for (let i = A.length - 1; i >= 0; i--) {
    if (adj[i] < B[i]) { if (i > 0) adj[i - 1] -= 1; c++; }
  }
  return c;
}

const nDigit = (n) => randInt(Math.pow(10, n - 1), Math.pow(10, n) - 1);

function reduce(n, d) {
  const g = gcd(n, d) || 1;
  return [n / g, d / g];
}

function randReducedFrac(maxD) {
  for (let t = 0; t < 60; t++) {
    const d = randInt(2, maxD), n = randInt(1, d - 1);
    if (gcd(n, d) === 1) return [n, d];
  }
  return [1, 2];
}

// in-session hot streak, 4 levels — lights at 4, 9, 14 and 18 right in a row.
// One ladder drives everything that reacts to a streak: the pet's charge glow, the
// sheet glow and the combo shout, so they always step up together.
const STREAK_TIERS = [
  { at: 4, label: "COMBO!", color: "#35E0FF" },
  { at: 9, label: "SUPER COMBO!", color: "#8A5CFF" },
  { at: 14, label: "HYPER COMBO!", color: "#FF2DA8" },
  { at: 18, label: "ULTRA COMBO!!", color: "#FFB020" },
];
const streakTier = (s) => STREAK_TIERS.reduce((n, t, i) => (s >= t.at ? i + 1 : n), 0); // 0 = cold
// the shout's colour comes from the tier; its words from the equipped pack (SHOUT_PACKS, defined with the shop)
const comboTier = (s, packId) => {
  const t = Math.max(0, streakTier(s) - 1);
  const pack = (packId && SHOUT_PACKS[packId]) || null;
  return { label: pack ? pack.labels[t] : STREAK_TIERS[t].label, color: STREAK_TIERS[t].color, cls: pack ? pack.cls : "" };
};

