// ---------- level routes: the map traces the letter of the level ----------
// route: one continuous polyline through the glyph. The 5 check points ride it at 1/6…5/6 of its
// length, the 🔓 exit sits at the end. extra: strokes that finish the letter but carry no nodes.
// Coordinates live in a 200×240 box; the <svg> viewBox pads it for node glow.
// `at` overrides where the 5 check points sit along the route (default: evenly, at 1/6…5/6) for
// letters whose stroke lengths are lopsided enough that even spacing bunches nodes on a corner.
const LETTER_ROUTES = {
  A: { route: [[36, 226], [68, 128], [100, 16], [132, 128], [164, 226]], extra: [[[59, 156], [141, 156]]] },
  B: { route: [[56, 226], [56, 14], [110, 14], [136, 26], [146, 50], [138, 82], [112, 100], [56, 100], [122, 100], [156, 116], [168, 152], [160, 196], [126, 226], [56, 226]], extra: [], at: [0.09, 0.33, 0.44, 0.66, 0.85] },
  C: { route: [[156, 54], [136, 28], [108, 16], [76, 22], [52, 44], [40, 80], [38, 120], [44, 164], [62, 198], [92, 222], [124, 224], [150, 206], [158, 186]], extra: [] },
  D: { route: [[56, 226], [56, 14], [104, 14], [136, 28], [156, 60], [162, 120], [156, 180], [136, 212], [104, 226], [56, 226]], extra: [] },
  E: { route: [[158, 16], [56, 16], [56, 226], [158, 226]], extra: [[[56, 121], [140, 121]]] },
  F: { route: [[158, 16], [56, 16], [56, 226]], extra: [[[56, 126], [138, 126]]], at: [0.05, 0.26, 0.48, 0.7, 0.91] },
};
// each check point gets its own neon — they all used to render the same colour
const CP_COLORS = ["#35E0FF", "#2DFFB3", "#FFB020", "#FF2DA8", "#8A5CFF"];
const cpAt = (g, t) => (g.at ? g.at[t - 1] : t / 6);
// how much of the route is lit: check point t is reached at paper t×20, and the last stretch
// (check point 5 → the exit) only lights once every check point is cleared.
function energyFor(g, papers, allCleared) {
  if (allCleared) return 1;
  const p = Math.max(0, Math.min(100, papers));
  const i = Math.floor(p / 20);
  const a = i === 0 ? 0 : cpAt(g, i);
  const b = i >= 5 ? 1 : cpAt(g, i + 1);
  return a + (b - a) * ((p % 20) / 20);
}

const routeLen = (r) => r.reduce((s, p, i) => (i ? s + Math.hypot(p[0] - r[i - 1][0], p[1] - r[i - 1][1]) : 0), 0);
const routeD = (r) => r.map((p, i) => `${i ? "L" : "M"}${p[0]} ${p[1]}`).join(" ");
// point at fraction f (0…1) of a polyline's arc length
function pointAt(r, f) {
  const segs = r.slice(1).map((p, i) => Math.hypot(p[0] - r[i][0], p[1] - r[i][1]));
  let want = Math.max(0, Math.min(1, f)) * segs.reduce((a, b) => a + b, 0);
  for (let i = 0; i < segs.length; i++) {
    if (want <= segs[i] || i === segs.length - 1) {
      const k = segs[i] ? Math.min(1, want / segs[i]) : 0;
      return [r[i][0] + (r[i + 1][0] - r[i][0]) * k, r[i][1] + (r[i + 1][1] - r[i][1]) * k];
    }
    want -= segs[i];
  }
  return r[r.length - 1];
}

// ---------- question generators ----------
// Every question: { display, answer }
// display: {layout:'stack', top, bottom, sym} | {layout:'inline', text}
//        | {layout:'frac', pre?, parts:[{n,d}|{sym}], }
// answer: {type:'int', v} | {type:'frac', n, d}  (frac stored reduced)

function genAddition(tier) {
  for (let t = 0; t < 300; t++) {
    let a, b;
    if (tier === 1) { a = nDigit(3); b = nDigit(2); }
    else if (tier === 2) { a = nDigit(3); b = nDigit(3); }
    else if (tier === 3) { a = nDigit(3); b = nDigit(3); }
    else if (tier === 4) { a = nDigit(4); b = nDigit(3); }
    else { a = nDigit(4); b = nDigit(4); }
    const need = tier === 1 ? 1 : 2;
    if (countCarries(a, b) >= need)
      return { display: { layout: "stack", top: a, bottom: b, sym: "+" }, answer: { type: "int", v: a + b } };
  }
  return { display: { layout: "stack", top: 199, bottom: 99, sym: "+" }, answer: { type: "int", v: 298 } };
}

function genSubtraction(tier) {
  for (let t = 0; t < 300; t++) {
    let a, b;
    if (tier === 1) { a = nDigit(3); b = randInt(10, Math.min(99, a - 1)); }
    else if (tier === 2) { a = nDigit(3); b = randInt(100, a - 1); }
    else if (tier === 3) { a = nDigit(4); b = randInt(100, 999); }
    else if (tier === 4) { a = nDigit(4); b = randInt(1000, a - 1); }
    else { a = nDigit(4); b = randInt(1000, a - 1); }
    if (b >= a) continue;
    const need = tier <= 2 ? 1 : 2;
    if (countBorrows(a, b) >= need)
      return { display: { layout: "stack", top: a, bottom: b, sym: "−" }, answer: { type: "int", v: a - b } };
  }
  return { display: { layout: "stack", top: 402, bottom: 178, sym: "−" }, answer: { type: "int", v: 224 } };
}

function genMultiplication(tier) {
  let a, b;
  if (tier === 1) { a = randInt(3, 9); b = randInt(3, 9); }
  else if (tier === 2) { a = randInt(12, 99); b = randInt(3, 9); }
  else if (tier === 3) { a = randInt(102, 999); b = randInt(3, 9); }
  else if (tier === 4) { a = randInt(12, 99); b = randInt(12, 99); }
  else { a = randInt(102, 999); b = randInt(12, 99); }
  return { display: { layout: "stack", top: a, bottom: b, sym: "×" }, answer: { type: "int", v: a * b } };
}

function genDivision(tier) {
  let d, q;
  if (tier === 1) { d = randInt(2, 9); q = randInt(2, 9); }
  else if (tier === 2) { d = randInt(2, 9); q = randInt(3, 12); }
  else if (tier === 3) { d = randInt(3, 9); q = randInt(12, 99); }
  else if (tier === 4) { d = randInt(3, 9); q = randInt(102, 999); }
  else { d = randInt(11, 25); q = randInt(12, 99); }
  return { display: { layout: "inline", text: `${fmt(d * q)} ÷ ${d} =` }, answer: { type: "int", v: q } };
}

function genFractions1(tier) {
  if (tier === 1) {
    const [n, d] = randReducedFrac(9);
    const k = randInt(2, 6);
    return {
      display: { layout: "frac", pre: "Simplify:", parts: [{ n: n * k, d: d * k }] },
      answer: { type: "frac", n, d },
    };
  }
  const maxD = tier <= 3 ? 12 : 15;
  const d = randInt(4, maxD);
  let n1, n2, sym;
  if (tier === 2 || (tier >= 4 && Math.random() < 0.5)) {
    sym = "+"; n1 = randInt(1, d - 2); n2 = randInt(1, tier === 5 ? d - 1 : d - 1 - n1 > 0 ? d - 1 - n1 : 1);
  } else {
    sym = "−"; n1 = randInt(2, d - 1); n2 = randInt(1, n1 - 1);
  }
  const rawN = sym === "+" ? n1 + n2 : n1 - n2;
  const [rn, rd] = reduce(rawN, d);
  return {
    display: { layout: "frac", parts: [{ n: n1, d }, { sym }, { n: n2, d }] },
    answer: rd === 1 ? { type: "int", v: rn } : { type: "frac", n: rn, d: rd },
  };
}

function genFractions2(tier) {
  const maxD = tier === 5 ? 12 : 8;
  const pick = tier === 5 ? randInt(1, 4) : Math.min(tier, 4);
  let [n1, d1] = randReducedFrac(maxD);
  let [n2, d2] = randReducedFrac(maxD);
  let sym, rn, rd;
  if (pick === 1) { sym = "+"; rn = n1 * d2 + n2 * d1; rd = d1 * d2; }
  else if (pick === 2) {
    if (n1 / d1 < n2 / d2) { [n1, d1, n2, d2] = [n2, d2, n1, d1]; }
    if (n1 * d2 === n2 * d1) { n2 = Math.max(1, n2 - 1); }
    sym = "−"; rn = n1 * d2 - n2 * d1; rd = d1 * d2;
  }
  else if (pick === 3) { sym = "×"; rn = n1 * n2; rd = d1 * d2; }
  else { sym = "÷"; rn = n1 * d2; rd = d1 * n2; }
  const [an, ad] = reduce(rn, rd);
  return {
    display: { layout: "frac", parts: [{ n: n1, d: d1 }, { sym }, { n: n2, d: d2 }] },
    answer: ad === 1 ? { type: "int", v: an } : { type: "frac", n: an, d: ad },
  };
}

const GEN = [genAddition, genSubtraction, genMultiplication, genDivision, genFractions1, genFractions2];

function buildSession(levelIdx, startPaper) {
  const qs = [];
  for (let p = startPaper; p < startPaper + PAPERS_PER_SESSION; p++) {
    for (let i = 0; i < Q_PER_PAPER; i++) {
      qs.push({ paper: p, ...GEN[levelIdx](tierOf(p)) });
    }
  }
  return qs;
}

function buildBossQs(levelIdx, tierEndPaper) {
  const qs = [];
  for (let i = 0; i < 25; i++) {
    const p = tierEndPaper - 19 + Math.floor(Math.random() * 20);
    qs.push({ paper: p, qLevel: levelIdx, ...GEN[levelIdx](tierOf(p)) });
  }
  return qs;
}

function buildScanQs(level) {
  const qs = [];
  const push = (li) => {
    const p = 1 + Math.floor(Math.random() * PAPERS_PER_LEVEL);
    qs.push({ paper: p, qLevel: li, ...GEN[li](tierOf(p)) });
  };
  for (let i = 0; i < 10; i++) push(level);
  for (let i = 0; i < 15; i++) push(level > 0 ? Math.floor(Math.random() * level) : 0);
  for (let i = qs.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [qs[i], qs[j]] = [qs[j], qs[i]]; }
  return qs;
}

// ---------- answers ----------

function answerToString(ans) {
  return ans.type === "int" ? fmt(ans.v) : `${ans.n}/${ans.d}`;
}

function checkAnswer(input, ans) {
  const s = input.trim();
  if (s === "") return false;
  if (s.includes("/")) {
    const [pn, pd] = s.split("/").map((x) => parseInt(x, 10));
    if (!Number.isFinite(pn) || !Number.isFinite(pd) || pd === 0) return false;
    const [rn, rd] = reduce(pn, pd);
    if (ans.type === "frac") return rn === ans.n && rd === ans.d;
    return rd === 1 && rn === ans.v;
  }
  const v = parseInt(s, 10);
  if (!Number.isFinite(v)) return false;
  return ans.type === "int" ? v === ans.v : false;
}

