const deviceId = () => {
  try {
    let id = localStorage.getItem("kumon-device");
    if (!id) { id = Math.random().toString(36).slice(2, 8); localStorage.setItem("kumon-device", id); }
    return id;
  } catch (e) { return "?"; }
};
const uniq = (arr) => [...new Set(arr)];
