// ---------- prize wallet ----------
// Every PASS = ¥100. Every completed block of 3 CONSECUTIVE days
// (days with at least one pass) earns a bonus ¥100.
// Example: 3 days in a row, 3 passes → ¥300 + ¥100 = ¥400.
// Days 4-5-6 consecutive with 3 more passes → another ¥400. Total ¥800.

const todayISO = () => new Date().toLocaleDateString("en-CA"); // YYYY-MM-DD local

// ---------- Stage 1 economy: dual currency ----------
// Every earn event sits behind the 100% pass gate.
// Session pass: +50 GC / +100 RP · streak block: +50/+100 · boss & scan: double.
const GC_PASS = 50, RP_PASS = 100;

function computeEconomy(history, shieldDays) {
  let gc = 0, rp = 0, passes = 0;
  history.forEach((h) => {
    if (!h.passed) return;
    passes++;
    const mult = h.boss || h.scan ? 2 : 1;
    gc += GC_PASS * mult;
    rp += RP_PASS * mult;
  });
  const dayset = new Set(history.filter((h) => h.passed && !h.scan && h.date).map((h) => h.date));
  (shieldDays || []).forEach((d) => dayset.add(d));
  const passDays = [...dayset].sort();
  let bonuses = 0, run = 0, prev = null;
  for (const d of passDays) {
    run = prev && Date.parse(d) - Date.parse(prev) === 86400000 ? run + 1 : 1;
    if (run % 3 === 0) bonuses++;
    prev = d;
  }
  gc += bonuses * GC_PASS;
  rp += bonuses * RP_PASS;
  const last = passDays[passDays.length - 1];
  const gap = last ? Math.round((Date.parse(todayISO()) - Date.parse(last)) / 86400000) : Infinity;
  const liveRun = gap <= 1 ? run : 0;
  return { gc, rp, passes, bonuses, liveRun };
}
