// Old bug: hard slice(0,40) pushed PASS rows out as quits piled up,
// silently deleting earned coins (and making a fresh pass net +0).
function trimHistory(h) {
  const out = [];
  let quits = 0, qlogs = 0;
  for (const r of h) {
    if (r.quit || r.restart) {
      if (quits < 15) { out.push(r); quits++; }
      continue;
    }
    const row = { ...r };
    if (row.qlog) { qlogs++; if (qlogs > 30) delete row.qlog; } // bound size, keep recent heatmap data
    out.push(row);
  }
  return out.slice(0, 400);
}

const FRESH_WALLET = () => ({
  gcSpent: 0, rpSpent: 0, inventory: [], activePet: null, activeFx: null,
  activeSnd: null, activeBg: null, ring: null, shields: 0, shieldDays: [],
  redemptions: [], lastScanWeek: null,
});

function balances(p) {
  const eco = computeEconomy(p.history, p.wallet ? p.wallet.shieldDays : []);
  return {
    ...eco,
    gcBal: eco.gc - (p.wallet ? p.wallet.gcSpent : 0),
    rpBal: eco.rp - (p.wallet ? p.wallet.rpSpent : 0),
  };
}

function isoWeek(d) {
  const t = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const day = t.getUTCDay() || 7;
  t.setUTCDate(t.getUTCDate() + 4 - day);
  const y0 = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
  return `${t.getUTCFullYear()}-W${String(Math.ceil(((t - y0) / 86400000 + 1) / 7)).padStart(2, "0")}`;
}

