async function loadProgress(name) {
  // Cloud and local are MERGED, never picked. Cloud used to win outright, so a pass saved on a device
  // whose cloud write never landed (iPhone put to sleep a second after the summary) was thrown away
  // the next time the app opened. Now it comes back and gets pushed up.
  const cloud = await cloudLoad(name);
  const local = localLoad(name);
  let p = cloud && local ? mergeProgress(cloud, local) : cloud || local || freshProgress();
  if (!p || !Array.isArray(p.history)) p = freshProgress();
  const recovered = !!(cloud && local) && !sameProgress(p, cloud);

  // TestBot sandbox: preloaded rich vault (negative "spent" = free balance),
  // mid-level position so bosses/heatmap/scan states are all reachable
  if (name.toLowerCase() === "testbot" && !p.testSeeded) {
    p = testSeed();
  }

  let changed = recovered;

  // migration: older entries had no date stamp
  p.history.forEach((h) => {
    if (h.passed && !h.date) { h.date = new Date().toLocaleDateString("en-CA"); changed = true; }
  });

  // bootstrap sync (28 Aug 2026): backfill known passes with real dates so a
  // completely fresh device reconstructs the right wallets and streaks.
  const SEED_SYNC = {
    geralt: { paper: 66, sessions: [["1–5", "2026-08-25"], ["6–10", "2026-08-25"], ["11–15", "2026-08-25"], ["16–20", "2026-08-26"], ["21–25", "2026-08-26"], ["26–30", "2026-08-27"], ["31–35", "2026-08-27"], ["36–40", "2026-08-27"], ["41–45", "2026-08-27"], ["46–50", "2026-08-27"], ["51–55", "2026-08-27"], ["56–60", "2026-08-27"], ["61–65", "2026-08-28"]] },
    allison: { paper: 41, sessions: [["1–5", "2026-08-25"], ["6–10", "2026-08-26"], ["11–15", "2026-08-26"], ["16–20", "2026-08-27"], ["21–25", "2026-08-27"], ["26–30", "2026-08-27"], ["31–35", "2026-08-27"], ["36–40", "2026-08-28"]] },
  };
  const seed = SEED_SYNC[name.toLowerCase()];
  if (seed && p.level === 0 && p.paper < seed.paper) {
    seed.sessions.forEach(([rg, dt]) => {
      if (!p.history.some((h) => h.passed && h.levelId === "A" && h.papers === rg)) {
        p.history.unshift({
          date: dt, when: dt + " (logged by Dad)",
          levelIdx: 0, levelId: "A", papers: rg,
          correct: 25, incorrect: 0, timeout: 0, total: 25,
          passed: true, mins: "—",
        });
      }
    });
    p.paper = seed.paper;
    changed = true;
  }

  // Stage 1 migration: wallet + boss gates arrive
  if (!p.wallet) { p.wallet = FRESH_WALLET(); changed = true; }
  else p.wallet = { ...FRESH_WALLET(), ...p.wallet };

  // One-time history repair (30 Aug 2026): the old slice(0,40) cap evicted
  // early PASS rows as quits piled up, deleting earned coins. Restore the
  // canonical early passes recovered from the Google Drive kumon-log files.
  const REPAIR_ROWS = {
    allison: [
    { date: "2026-08-25", when: "8/25/2026 05:41 PM", levelIdx: 0, levelId: "A", papers: "1–5", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "4:15" },
    { date: "2026-08-26", when: "2026-08-26 (logged by Dad)", levelIdx: 0, levelId: "A", papers: "6–10", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "—" },
    { date: "2026-08-26", when: "2026-08-26 (logged by Dad)", levelIdx: 0, levelId: "A", papers: "11–15", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "—" },
    { date: "2026-08-27", when: "2026-08-27 (logged by Dad)", levelIdx: 0, levelId: "A", papers: "16–20", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "—" },
    { date: "2026-08-27", when: "2026-08-27 (logged by Dad)", levelIdx: 0, levelId: "A", papers: "21–25", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "—" },
    { date: "2026-08-27", when: "8/27/2026 03:16 PM", levelIdx: 0, levelId: "A", papers: "26–30", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "5:29" },
    { date: "2026-08-27", when: "8/27/2026 (logged by Dad)", levelIdx: 0, levelId: "A", papers: "31–35", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "—" },
    { date: "2026-08-28", when: "8/28/2026 (logged by Dad)", levelIdx: 0, levelId: "A", papers: "36–40", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "—" }
    ],
    geralt: [
    { date: "2026-08-25", when: "8/25/2026 05:34 PM", levelIdx: 0, levelId: "A", papers: "1–5", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "6:12" },
    { date: "2026-08-25", when: "8/25/2026 06:58 PM", levelIdx: 0, levelId: "A", papers: "6–10", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "5:16" },
    { date: "2026-08-25", when: "8/25/2026 07:33 PM", levelIdx: 0, levelId: "A", papers: "11–15", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "6:07" },
    { date: "2026-08-26", when: "2026-08-26 (logged by Dad)", levelIdx: 0, levelId: "A", papers: "16–20", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "—" },
    { date: "2026-08-26", when: "2026-08-26 (logged by Dad)", levelIdx: 0, levelId: "A", papers: "21–25", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "—" },
    { date: "2026-08-27", when: "8/27/2026 12:56 PM", levelIdx: 0, levelId: "A", papers: "26–30", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "5:32" },
    { date: "2026-08-27", when: "8/27/2026 01:06 PM", levelIdx: 0, levelId: "A", papers: "31–35", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "6:01" },
    { date: "2026-08-27", when: "2026-08-27 (logged by Dad)", levelIdx: 0, levelId: "A", papers: "36–40", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "—" },
    { date: "2026-08-27", when: "2026-08-27 (logged by Dad)", levelIdx: 0, levelId: "A", papers: "41–45", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "—" },
    { date: "2026-08-27", when: "8/27/2026 03:32 PM", levelIdx: 0, levelId: "A", papers: "46–50", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "6:01" },
    { date: "2026-08-27", when: "8/27/2026 03:39 PM", levelIdx: 0, levelId: "A", papers: "51–55", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "6:14" },
    { date: "2026-08-27", when: "8/27/2026 (logged by Dad)", levelIdx: 0, levelId: "A", papers: "56–60", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "—" }
    ],
  };
  const repair = REPAIR_ROWS[name.toLowerCase()];
  if (repair && !p.wallet.histRepair2) {
    const rowKey = (r) => r.date + "|" + r.papers + "|" + (r.passed ? 1 : 0);
    const have = new Set(p.history.map(rowKey));
    const missing = repair.filter((r) => !have.has(rowKey(r)));
    if (missing.length) p.history = [...p.history, ...missing]; // oldest at the end
    p.wallet.histRepair2 = true;
    changed = true;
  }

  // Hard guard (1 Sep 2026): a check point can only be cleared once its tier is
  // actually completed (every 20 papers, max 5). A stale build let Allison fight
  // T3–T6 at papers 51–56, inflating bossCleared and paying phantom double loot.
  // Clamp bossCleared to the legit count and void the surplus check-point rows.
  {
    const legit = Math.min(5, Math.floor((Math.max(1, p.paper) - 1) / 20));
    if (typeof p.bossCleared === "number" && p.bossCleared > legit) {
      let surplus = p.bossCleared - legit;
      p.history = p.history.filter((r) => {
        if (r.boss && r.passed && surplus > 0) { surplus--; return false; } // newest-first: drop the phantom ones
        return true;
      });
      p.bossCleared = legit;
      changed = true;
    }
  }

  // One-time credit (1 Sep 2026): the stale-build check point Allison passed today
  // took the place of her real session (A 56–60). Credit that session instead.
  if (name.toLowerCase() === "allison" && !p.wallet.sessionFix4) {
    const hasIt = p.history.some((r) => r.passed && r.levelIdx === 0 && r.papers === "56–60");
    if (!hasIt && p.level === 0 && p.paper <= 56) {
      p.history = [{ date: "2026-09-01", when: "9/1/2026 (credited by Dad — CP bug)", levelIdx: 0, levelId: "A", papers: "56–60", correct: 25, incorrect: 0, timeout: 0, total: 25, passed: true, mins: "—" }, ...p.history];
      p.paper = 61;
    }
    p.wallet.sessionFix4 = true;
    changed = true;
  }

  // Purchase ledger backfill (1 Sep 2026): reconstruct pre-ledger purchases from inventory
  if (!p.wallet.purchasesInit) {
    const rows = (p.wallet.inventory || []).map((id) => {
      const it = SHOP_ITEMS.find((s) => s.id === id);
      return it ? { id, emoji: it.emoji, name: it.name, cost: it.cost, date: "—", when: "before ledger" } : null;
    }).filter(Boolean);
    const sum = rows.reduce((a, r) => a + r.cost, 0);
    const residual = (p.wallet.gcSpent || 0) - sum;
    if (residual > 0 && !(name.toLowerCase() === "testbot")) rows.push({ id: "other", emoji: "🛡️", name: "shields / earlier spending", cost: residual, date: "—", when: "before ledger" });
    p.wallet.purchases = [...rows, ...(p.wallet.purchases || [])];
    p.wallet.purchasesInit = true;
    changed = true;
  }

  // self-heal old quit pileups from the pre-fix cap era
  if (p.history.filter((r) => r.quit || r.restart).length > 15 || p.history.length > 400) {
    p.history = trimHistory(p.history);
    changed = true;
  }

  // One-time streak correction (30 Aug 2026): Allison's seed started at 27 Aug
  // but her real chain began 25 Aug like Geralt's — credit the two missing days
  // as shield days (streak continuity without fabricating passes).
  if (name.toLowerCase() === "allison" && !p.wallet.streakFix1) {
    const sd = new Set(p.wallet.shieldDays || []);
    sd.add("2026-08-25"); sd.add("2026-08-26");
    p.wallet.shieldDays = [...sd].sort();
    p.wallet.streakFix1 = true;
    changed = true;
  }
  if (typeof p.bossCleared !== "number") {
    p.bossCleared = Math.min(5, Math.max(0, Math.floor((p.paper - 1) / 20)));
    changed = true;
  }

  // streak shield auto-consume: yesterday had no pass, the day before kept a
  // chain, and a shield is held — burn one to save the streak
  try {
    const today = todayISO();
    const yest = new Date(Date.parse(today) - 86400000).toISOString().slice(0, 10);
    const dayBefore = new Date(Date.parse(today) - 2 * 86400000).toISOString().slice(0, 10);
    const days = new Set(p.history.filter((h) => h.passed && !h.scan && h.date).map((h) => h.date));
    (p.wallet.shieldDays || []).forEach((d) => days.add(d));
    if (p.wallet.shields > 0 && !days.has(yest) && days.has(dayBefore)) {
      p.wallet.shields -= 1;
      p.wallet.shieldDays = [...(p.wallet.shieldDays || []), yest];
      p.history.unshift({ date: yest, ts: Date.now(), when: yest + " 🛡️", levelIdx: p.level, levelId: LEVELS[p.level].id, papers: "—", shield: true });
      changed = true;
    }
  } catch (e) {}

  if (changed) saveProgress(name, p);
  else localSave(name, p); // keep the local cache warm
  return p;
}

async function saveProgress(name, data) {
  const stamped = { ...data, savedAt: Date.now(), savedBy: deviceId() };
  localSave(name, stamped);           // instant, never fails silently on us
  return cloudSave(name, stamped);    // resolves true when the cloud write landed
}

